use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    let mut handles = Vec::new();
    for i in 0..4u64 {
        let tx = tx.clone();
        handles.push(thread::spawn(move || {
            let start = i * 250 + 1;
            let end = (i + 1) * 250;
            let partial: u64 = (start..=end).sum();
            tx.send(partial).expect("send");
        }));
    }
    drop(tx);
    let total: u64 = rx.iter().sum();
    for h in handles {
        h.join().expect("join");
    }
    println!("total: {total}");
}
